/// Light or dark appearance.
public enum MistyAppearance: Sendable {
    case light
    case dark
}

/// An sRGB colour with channels from 0 to 1.
public struct MistyRGBA: Sendable, Equatable {
    public let red: Double
    public let green: Double
    public let blue: Double
    public let alpha: Double

    public init(red: Double, green: Double, blue: Double, alpha: Double) {
        self.red = red
        self.green = green
        self.blue = blue
        self.alpha = alpha
    }

    /// The colour as #RRGGBB, without alpha.
    public var hex: String {
        String(format: "#%02X%02X%02X", Int((red * 255).rounded()), Int((green * 255).rounded()), Int((blue * 255).rounded()))
    }

    #if canImport(SwiftUI)
    public var color: Color { Color(.sRGB, red: red, green: green, blue: blue, opacity: alpha) }
    #endif
}

/// An OKLCH colour. When `followsHue` is true, `h` is an offset from the Misty hue.
public struct MistyOKLCH: Sendable, Equatable {
    public let l: Double
    public let c: Double
    public let h: Double
    public let alpha: Double
    public let followsHue: Bool

    public init(_ l: Double, _ c: Double, _ h: Double, alpha: Double = 1, followsHue: Bool) {
        self.l = l
        self.c = c
        self.h = h
        self.alpha = alpha
        self.followsHue = followsHue
    }

    /// sRGB channels, clipped per channel as browsers do on sRGB displays.
    public func rgba(hue: Double) -> MistyRGBA {
        let angle = (followsHue ? hue + h : h) * Double.pi / 180
        let a = c * cos(angle)
        let b = c * sin(angle)
        let l3 = pow(l + 0.3963377774 * a + 0.2158037573 * b, 3)
        let m3 = pow(l - 0.1055613458 * a - 0.0638541728 * b, 3)
        let s3 = pow(l - 0.0894841775 * a - 1.2914855480 * b, 3)
        func encode(_ v: Double) -> Double {
            let g = v <= 0.0031308 ? 12.92 * v : 1.055 * pow(v, 1 / 2.4) - 0.055
            return min(1, max(0, g))
        }
        return MistyRGBA(
            red: encode(4.0767416621 * l3 - 3.3077115913 * m3 + 0.2309699292 * s3),
            green: encode(-1.2684380046 * l3 + 2.6097574011 * m3 - 0.3413193965 * s3),
            blue: encode(-0.0041960863 * l3 - 0.7034186147 * m3 + 1.7076147010 * s3),
            alpha: alpha
        )
    }
}

/// A colour token with a light and a dark value.
public struct MistyThemedColor: Sendable {
    public let light: MistyOKLCH
    public let dark: MistyOKLCH

    public init(light: MistyOKLCH, dark: MistyOKLCH) {
        self.light = light
        self.dark = dark
    }

    public func rgba(hue: Double, appearance: MistyAppearance) -> MistyRGBA {
        (appearance == .dark ? dark : light).rgba(hue: hue)
    }
}

/// The translucent grades of glass. Cloud is solid: use the `cloud` colour.
public enum MistyGlassGrade: Sendable {
    case clear
    case mist
    case veil
}

