/// Glass: a tint of the field at a grade's alpha, over a blur of what lies behind.
public enum MistyGlass {
    public static let lightness = (light: 0.995, dark: 0.215)
    public static let chroma = (light: 0.004, dark: 0.02)
    /// Backdrop saturation, as a multiplier.
    public static let saturation: Double = 1.75

    public static func alpha(_ grade: MistyGlassGrade, _ appearance: MistyAppearance) -> Double {
        let dark = appearance == .dark
        switch grade {
        case .clear: return dark ? 0.36 : 0.3
        case .mist: return dark ? 0.5 : 0.42
        case .veil: return dark ? 0.68 : 0.62
        }
    }

    /// The blur's standard deviation in points, as in CSS.
    public static func blur(_ grade: MistyGlassGrade) -> CGFloat {
        switch grade {
        case .clear: return 24
        case .mist: return 26
        case .veil: return 32
        }
    }
}

/// Resolves Misty's colours for one hue and appearance.
public struct MistyTheme: Sendable {
    public var hue: Double
    public var appearance: MistyAppearance

    public init(hue: Double = 250.0, appearance: MistyAppearance = .light) {
        self.hue = hue
        self.appearance = appearance
    }

    public func rgba(_ token: MistyThemedColor) -> MistyRGBA {
        token.rgba(hue: hue, appearance: appearance)
    }

    /// The fill of a glass grade, before blur.
    public func glassFill(_ grade: MistyGlassGrade) -> MistyRGBA {
        let dark = appearance == .dark
        return MistyOKLCH(dark ? MistyGlass.lightness.dark : MistyGlass.lightness.light,
                          dark ? MistyGlass.chroma.dark : MistyGlass.chroma.light, 0,
                          alpha: MistyGlass.alpha(grade, appearance), followsHue: true).rgba(hue: hue)
    }

    #if canImport(SwiftUI)
    public var sky: Color { rgba(MistyColorToken.sky).color }
    public var skyHigh: Color { rgba(MistyColorToken.skyHigh).color }
    public var aurora1: Color { rgba(MistyColorToken.aurora1).color }
    public var aurora2: Color { rgba(MistyColorToken.aurora2).color }
