/// Durations and curves. Pass the curves to `Animation.timingCurve` unchanged.
public enum MistyMotion {
    public static let duration0: TimeInterval = 0.08
    public static let duration1: TimeInterval = 0.16
    public static let duration2: TimeInterval = 0.24
    public static let duration3: TimeInterval = 0.38
    public static let duration4: TimeInterval = 0.6
    public static let fluidCurve = (0.22, 1.0, 0.36, 1.0)
    public static let springCurve = (0.34, 1.36, 0.64, 1.0)
    public static let exitCurve = (0.4, 0.0, 1.0, 1.0)

    #if canImport(SwiftUI)
    public static func fluid(duration: TimeInterval) -> Animation {
        .timingCurve(0.22, 1.0, 0.36, 1.0, duration: duration)
    }
    public static func spring(duration: TimeInterval) -> Animation {
        .timingCurve(0.34, 1.36, 0.64, 1.0, duration: duration)
    }
    public static func exit(duration: TimeInterval) -> Animation {
        .timingCurve(0.4, 0.0, 1.0, 1.0, duration: duration)
    }
    #endif
}

/// Fluid type sizes in points, from the window's width in points. The platform then
/// scales them with the person's text size setting (PLT-06).
public enum MistyType {
    static func clamp(_ low: CGFloat, _ value: CGFloat, _ high: CGFloat) -> CGFloat { min(max(low, value), high) }
    public static func display(width: CGFloat) -> CGFloat { clamp(52, width * 0.066, 92) }
    public static func h1(width: CGFloat) -> CGFloat { clamp(38.4, width * 0.046, 60) }
    public static func h2(width: CGFloat) -> CGFloat { clamp(30.4, width * 0.034, 44) }
    public static func h3(width: CGFloat) -> CGFloat { clamp(20.8, width * 0.02, 24) }
    public static func lede(width: CGFloat) -> CGFloat { clamp(17, width * 0.015, 19) }
    /// The longest line of running text, in characters.
    public static let measure = 68
}

/// Page widths and fluid spacing in points.
public enum MistyLayout {
    public static let page: CGFloat = 1200
    public static let pageDocs: CGFloat = 1312
    public static let reading: CGFloat = 704
    public static let navHeight: CGFloat = 72
    public static func gutter(width: CGFloat) -> CGFloat { min(max(18, width * 0.04), 32) }
    public static func section(width: CGFloat) -> CGFloat { min(max(64, width * 0.09), 120) }
}

/// The five window classes, measured on the window's width.
public enum MistyWindowClass: Sendable {
    case narrow, compact, medium, expanded, wide

    public init(width: CGFloat) {
        switch width {
        case ...380: self = .narrow
        case ...767: self = .compact
        case ...1023: self = .medium
        case ...1179: self = .expanded
        default: self = .wide
        }
    }
}

/// Elevation shadows. Each level has light and dark layers.
public enum MistyShadow {
    public static let level1Light: [MistyShadowLayer] = [MistyShadowLayer(x: 0, y: 1, blur: 2, spread: 0, color: MistyOKLCH(0.3, 0.04, 0.0, alpha: 0.04, followsHue: true)), MistyShadowLayer(x: 0, y: 10, blur: 28, spread: -18, color: MistyOKLCH(0.3, 0.06, 0.0, alpha: 0.22, followsHue: true))]
    public static let level1Dark: [MistyShadowLayer] = [MistyShadowLayer(x: 0, y: 1, blur: 2, spread: 0, color: MistyOKLCH(0.0, 0.0, 0.0, alpha: 0.22, followsHue: false)), MistyShadowLayer(x: 0, y: 12, blur: 30, spread: -16, color: MistyOKLCH(0.0, 0.0, 0.0, alpha: 0.55, followsHue: false))]
    public static let level2Light: [MistyShadowLayer] = [MistyShadowLayer(x: 0, y: 2, blur: 6, spread: 0, color: MistyOKLCH(0.3, 0.04, 0.0, alpha: 0.06, followsHue: true)), MistyShadowLayer(x: 0, y: 22, blur: 48, spread: -24, color: MistyOKLCH(0.3, 0.08, 0.0, alpha: 0.3, followsHue: true))]
    public static let level2Dark: [MistyShadowLayer] = [MistyShadowLayer(x: 0, y: 2, blur: 6, spread: 0, color: MistyOKLCH(0.0, 0.0, 0.0, alpha: 0.28, followsHue: false)), MistyShadowLayer(x: 0, y: 24, blur: 52, spread: -22, color: MistyOKLCH(0.0, 0.0, 0.0, alpha: 0.65, followsHue: false))]
    public static let level3Light: [MistyShadowLayer] = [MistyShadowLayer(x: 0, y: 8, blur: 24, spread: 0, color: MistyOKLCH(0.3, 0.04, 0.0, alpha: 0.1, followsHue: true)), MistyShadowLayer(x: 0, y: 40, blur: 80, spread: -30, color: MistyOKLCH(0.3, 0.1, 0.0, alpha: 0.38, followsHue: true))]
    public static let level3Dark: [MistyShadowLayer] = [MistyShadowLayer(x: 0, y: 8, blur: 24, spread: 0, color: MistyOKLCH(0.0, 0.0, 0.0, alpha: 0.35, followsHue: false)), MistyShadowLayer(x: 0, y: 44, blur: 84, spread: -28, color: MistyOKLCH(0.0, 0.0, 0.0, alpha: 0.78, followsHue: false))]

    public static func layers(level: Int, appearance: MistyAppearance) -> [MistyShadowLayer] {
        let dark = appearance == .dark
        switch level {
        case 1: return dark ? level1Dark : level1Light
        case 2: return dark ? level2Dark : level2Light
        case 3: return dark ? level3Dark : level3Light
        default: return []
        }
    }
}

